import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_03_01_control_vs_task.png",p="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_03_02_prompt_contract.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_03_03_four_workflows.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_03_06_interface_trust.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_03_04_vertical_delivery.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_03_07_feedback_evidence.png",P=JSON.parse('{"title":"AI 为什么会越改越准：Prompt、上下文与 Computer Use 的可信协作闭环","description":"AI 编程真正拉开差距的地方，不是第一句 Prompt 写得多华丽，而是能否建立一条可反复校正的协作闭环。一个成熟的任务，会先定义目标和边界，再让代理收集上下文、执行局部动作、报告证据，由人审查后继续收紧方向。每一次反馈都减少一点歧义，最终把“看起来能用”变成“有证据可验收”。","frontmatter":{"title":"AI 为什么会越改越准：Prompt、上下文与 Computer Use 的可信协作闭环","description":"AI 编程真正拉开差距的地方，不是第一句 Prompt 写得多华丽，而是能否建立一条可反复校正的协作闭环。一个成熟的任务，会先定义目标和边界，再让代理收集上下文、执行局部动作、报告证据，由人审查后继续收紧方向。每一次反馈都减少一点歧义，最终把“看起来能用”变成“有证据可验收”。","date":"2026-08-10","topic":"AI 底层学习","section":"Codex · 官方文档十讲","readingTime":8,"source":"2026-08-10/ai_codex_03_interaction_loop.md","status":"published","cover":"/article-assets/2026-08-10/ai_codex_03_01_control_vs_task.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-03-interaction-loop"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"AI 为什么会越改越准：Prompt、上下文与 Computer Use 的可信协作闭环"}],["meta",{"property":"og:description","content":"AI 编程真正拉开差距的地方，不是第一句 Prompt 写得多华丽，而是能否建立一条可反复校正的协作闭环。一个成熟的任务，会先定义目标和边界，再让代理收集上下文、执行局部动作、报告证据，由人审查后继续收紧方向。每一次反馈都减少一点歧义，最终把“看起来能用”变成“有证据可验收”。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-03-interaction-loop"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_03_01_control_vs_task.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"AI 为什么会越改越准：Prompt、上下文与 Computer Use 的可信协作闭环"}],["meta",{"name":"twitter:description","content":"AI 编程真正拉开差距的地方，不是第一句 Prompt 写得多华丽，而是能否建立一条可反复校正的协作闭环。一个成熟的任务，会先定义目标和边界，再让代理收集上下文、执行局部动作、报告证据，由人审查后继续收紧方向。每一次反馈都减少一点歧义，最终把“看起来能用”变成“有证据可验收”。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_03_01_control_vs_task.png"}]],"prev":{"text":"四种入口，一套大脑：从第一个任务到 AGENTS.md 的 Codex 上手地图","link":"/ai/ai-codex-02-four-entries-and-agents"},"next":{"text":"给 Codex 装上外接大脑：配置、记忆、MCP、子代理、Skills 与插件全解","link":"/ai/ai-codex-04-memory-mcp-skills"}},"headers":[],"relativePath":"ai/ai-codex-03-interaction-loop.md","filePath":"ai/ai-codex-03-interaction-loop.md","lastUpdated":null}'),h={name:"ai/ai-codex-03-interaction-loop.md"};function d(_,a,m,u,b,x){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="ai-为什么会越改越准-prompt、上下文与-computer-use-的可信协作闭环" tabindex="-1">AI 为什么会越改越准：Prompt、上下文与 Computer Use 的可信协作闭环 <a class="header-anchor" href="#ai-为什么会越改越准-prompt、上下文与-computer-use-的可信协作闭环" aria-label="Permalink to &quot;AI 为什么会越改越准：Prompt、上下文与 Computer Use 的可信协作闭环&quot;">​</a></h1><p>AI 编程真正拉开差距的地方，不是第一句 Prompt 写得多华丽，而是能否建立一条可反复校正的协作闭环。一个成熟的任务，会先定义目标和边界，再让代理收集上下文、执行局部动作、报告证据，由人审查后继续收紧方向。每一次反馈都减少一点歧义，最终把“看起来能用”变成“有证据可验收”。</p><p>本文以教程第 12～14、17、34 篇为线索，对照 OpenAI Docs 的 Prompting、Use cases 与 Computer Use 章节，覆盖会话控制、Prompt 结构、常见工程工作流、浏览器操作和完整项目交付。教程提供了容易上手的实践顺序，本文则以官方当前能力边界为准；权限与安全机制独立放在本系列第八篇展开。</p><h2 id="一、先分清任务内容与会话控制" tabindex="-1">一、先分清任务内容与会话控制 <a class="header-anchor" href="#一、先分清任务内容与会话控制" aria-label="Permalink to &quot;一、先分清任务内容与会话控制&quot;">​</a></h2><h3 id="_1-1-自然语言负责描述结果" tabindex="-1">1.1 自然语言负责描述结果 <a class="header-anchor" href="#_1-1-自然语言负责描述结果" aria-label="Permalink to &quot;1.1 自然语言负责描述结果&quot;">​</a></h3><p>你希望修复什么、不能改变什么、怎样才算成功，这些都应使用自然语言表达。代理需要理解业务语义、代码边界和验收条件，仅靠命令名称无法承载这些信息。</p><p>好的任务描述会把模糊愿望改写成可观察结果。例如，不说“优化登录”，而说清当前失败表现、允许修改的模块、兼容要求，以及必须通过的测试。目标越可验证，代理越容易主动闭环。</p><h3 id="_1-2-控制命令负责管理会话状态" tabindex="-1">1.2 控制命令负责管理会话状态 <a class="header-anchor" href="#_1-2-控制命令负责管理会话状态" aria-label="Permalink to &quot;1.2 控制命令负责管理会话状态&quot;">​</a></h3><p>查看当前模型、检查上下文、审阅差异、压缩历史、切换模式和结束会话，属于控制面。它们改变的是代理如何工作，而不是仓库要实现什么。</p><p>把两类信息混在一起，会产生典型误解：用户以为自己在限定任务，实际只切换了显示状态；或者把本应由任务说明表达的约束，寄托在某个短命令上。稳定用法是让 Prompt 管结果，让控制命令管会话。</p><p><img src="'+i+'" alt="图 1：任务平面与控制平面的职责边界"></p><h2 id="二、prompt-的本质是一份执行合同" tabindex="-1">二、Prompt 的本质是一份执行合同 <a class="header-anchor" href="#二、prompt-的本质是一份执行合同" aria-label="Permalink to &quot;二、Prompt 的本质是一份执行合同&quot;">​</a></h2><h3 id="_2-1-目标回答-最终要得到什么" tabindex="-1">2.1 目标回答“最终要得到什么” <a class="header-anchor" href="#_2-1-目标回答-最终要得到什么" aria-label="Permalink to &quot;2.1 目标回答“最终要得到什么”&quot;">​</a></h3><p>目标必须能够被验收。“看看这个项目”没有完成条件，“解释订单状态从 API 到数据库的流转，并指出三个可能丢失状态的位置”才有明确终点。</p><p>目标也不宜一次塞入多个互不相关的结果。代理可以处理复杂任务，但复杂不等于混乱。一个线程围绕一个主目标，后续判断会更清晰。</p><h3 id="_2-2-范围回答-能看哪里、能改哪里" tabindex="-1">2.2 范围回答“能看哪里、能改哪里” <a class="header-anchor" href="#_2-2-范围回答-能看哪里、能改哪里" aria-label="Permalink to &quot;2.2 范围回答“能看哪里、能改哪里”&quot;">​</a></h3><p>范围至少包含目录、文件、模块和外部系统边界。只读分析要明确不修改文件；实现任务要说明允许触碰的区域；涉及发布、删除、密钥和生产环境时，更要把禁止动作写出来。</p><p>范围不是为了束缚智能，而是为了降低搜索成本和误操作半径。代理知道边界后，反而能把更多计算放在真正相关的路径上。</p><h3 id="_2-3-约束回答-必须遵守什么" tabindex="-1">2.3 约束回答“必须遵守什么” <a class="header-anchor" href="#_2-3-约束回答-必须遵守什么" aria-label="Permalink to &quot;2.3 约束回答“必须遵守什么”&quot;">​</a></h3><p>语言版本、依赖策略、现有代码风格、兼容性、性能预算和安全规则都属于约束。最有效的约束是具体且可检查的，例如“不得增加新依赖”“只修改这个包”“保留公开 API”。</p><h3 id="_2-4-验证回答-用什么证据结束" tabindex="-1">2.4 验证回答“用什么证据结束” <a class="header-anchor" href="#_2-4-验证回答-用什么证据结束" aria-label="Permalink to &quot;2.4 验证回答“用什么证据结束”&quot;">​</a></h3><p>验证可以是测试、构建、静态检查、最小复现、运行日志或人工审查清单。没有验证的任务只能以代理自述结束，有验证的任务才能以外部证据结束。</p><p><img src="'+p+'" alt="图 2：目标、范围、约束、验证组成 Prompt 合同"></p><h2 id="三、探索、修复、重构与测试不是同一种工作" tabindex="-1">三、探索、修复、重构与测试不是同一种工作 <a class="header-anchor" href="#三、探索、修复、重构与测试不是同一种工作" aria-label="Permalink to &quot;三、探索、修复、重构与测试不是同一种工作&quot;">​</a></h2><h3 id="_3-1-探索阶段先建立地图" tabindex="-1">3.1 探索阶段先建立地图 <a class="header-anchor" href="#_3-1-探索阶段先建立地图" aria-label="Permalink to &quot;3.1 探索阶段先建立地图&quot;">​</a></h3><p>面对陌生仓库，先要求代理找入口、关键模块、数据流、配置源和测试命令。探索阶段的成果是事实地图，不是立刻产生代码。</p><p>如果代理在还没定位调用链时就开始重写，很可能只是把表面症状搬到另一个位置。探索应以文件、符号、命令输出和现有测试为证据。</p><h3 id="_3-2-修复阶段先复现再改变" tabindex="-1">3.2 修复阶段先复现再改变 <a class="header-anchor" href="#_3-2-修复阶段先复现再改变" aria-label="Permalink to &quot;3.2 修复阶段先复现再改变&quot;">​</a></h3><p>修复 bug 的可靠顺序是重现问题、定位根因、建立回归验证、做最小修改、重新运行验证。这里最关键的是区分“相关现象”和“确认原因”。</p><p>日志里靠近错误发生的警告，不一定就是根因；某段可疑代码，也不一定在失败路径上。让代理证明因果链，能避免靠猜测连续试错。</p><h3 id="_3-3-重构阶段先锁住行为" tabindex="-1">3.3 重构阶段先锁住行为 <a class="header-anchor" href="#_3-3-重构阶段先锁住行为" aria-label="Permalink to &quot;3.3 重构阶段先锁住行为&quot;">​</a></h3><p>重构的目标是改变结构而不改变外部行为。因此必须先找到已有测试、接口契约和调用方。若缺少保护网，应先补足能固定关键行为的测试，再进行小步结构调整。</p><p>一次性大改会让失败无法定位。更稳妥的是每一步都保持可构建、可测试、可审查。</p><h3 id="_3-4-测试阶段关注失败语义" tabindex="-1">3.4 测试阶段关注失败语义 <a class="header-anchor" href="#_3-4-测试阶段关注失败语义" aria-label="Permalink to &quot;3.4 测试阶段关注失败语义&quot;">​</a></h3><p>测试不只是让覆盖率数字上升。真正有价值的用例会验证边界输入、错误分支、状态变化和外部契约，并在实现错误时可靠失败。</p><p>代理生成测试后，人仍要检查它是否只复述当前实现，是否为了通过而弱化断言，以及是否遗漏最昂贵的失败场景。</p><p><img src="'+n+'" alt="图 3：四类工程任务的不同证据链"></p><h2 id="四、浏览器与-computer-use-扩大了动作空间" tabindex="-1">四、浏览器与 Computer Use 扩大了动作空间 <a class="header-anchor" href="#四、浏览器与-computer-use-扩大了动作空间" aria-label="Permalink to &quot;四、浏览器与 Computer Use 扩大了动作空间&quot;">​</a></h2><h3 id="_4-1-视觉操作适合没有稳定接口的界面" tabindex="-1">4.1 视觉操作适合没有稳定接口的界面 <a class="header-anchor" href="#_4-1-视觉操作适合没有稳定接口的界面" aria-label="Permalink to &quot;4.1 视觉操作适合没有稳定接口的界面&quot;">​</a></h3><p>当任务必须点击网页、观察渲染结果或操作只提供图形界面的应用时，Computer Use 能补足纯文本工具的缺口。它通过截图理解界面，再执行点击、输入和滚动。</p><p>这种能力更接近人在桌面上的操作，因此也更容易受到界面变化、遮挡、误点和恶意内容影响。它应被视为最后一公里工具，而不是替代稳定 API 的首选。</p><h3 id="_4-2-可验证接口优先于坐标点击" tabindex="-1">4.2 可验证接口优先于坐标点击 <a class="header-anchor" href="#_4-2-可验证接口优先于坐标点击" aria-label="Permalink to &quot;4.2 可验证接口优先于坐标点击&quot;">​</a></h3><p>如果同一目标可以通过官方 API、CLI 或结构化工具完成，通常应优先选择这些接口。结构化调用更容易记录输入输出、判断失败并重复执行；视觉点击则需要额外截图和人工确认。</p><h3 id="_4-3-登录、付款与发布保留人工确认" tabindex="-1">4.3 登录、付款与发布保留人工确认 <a class="header-anchor" href="#_4-3-登录、付款与发布保留人工确认" aria-label="Permalink to &quot;4.3 登录、付款与发布保留人工确认&quot;">​</a></h3><p>浏览器里最危险的不是打开页面，而是不可逆的最终提交。涉及账号授权、购买、发送消息、合并代码和公开发布时，应让代理准备到确认页，再由人核对关键字段并授权最后一步。</p><p><img src="'+s+'" alt="图 4：API、CLI 与视觉操作的信任梯度"></p><h2 id="五、让每一轮反馈都减少歧义" tabindex="-1">五、让每一轮反馈都减少歧义 <a class="header-anchor" href="#五、让每一轮反馈都减少歧义" aria-label="Permalink to &quot;五、让每一轮反馈都减少歧义&quot;">​</a></h2><h3 id="_5-1-用证据纠偏-不用情绪评价" tabindex="-1">5.1 用证据纠偏，不用情绪评价 <a class="header-anchor" href="#_5-1-用证据纠偏-不用情绪评价" aria-label="Permalink to &quot;5.1 用证据纠偏，不用情绪评价&quot;">​</a></h3><p>“还是不对”几乎不能提供新信息。更有效的反馈是指出具体文件、实际输出、预期输出和违反的约束，让代理据此缩小原因空间。</p><h3 id="_5-2-把大任务拆成可验收节点" tabindex="-1">5.2 把大任务拆成可验收节点 <a class="header-anchor" href="#_5-2-把大任务拆成可验收节点" aria-label="Permalink to &quot;5.2 把大任务拆成可验收节点&quot;">​</a></h3><p>复杂工作可以依次产出调查结论、实施方案、局部修改、验证结果和交付记录。每个节点都允许人修正方向，避免所有风险集中到最后。</p><h3 id="_5-3-结束条件要比开始指令更清楚" tabindex="-1">5.3 结束条件要比开始指令更清楚 <a class="header-anchor" href="#_5-3-结束条件要比开始指令更清楚" aria-label="Permalink to &quot;5.3 结束条件要比开始指令更清楚&quot;">​</a></h3><p>任务完成不等于代理停止输出，而是所有要求都有对应证据，未完成项和风险被明确记录，没有越界修改。把结束条件写进 Prompt，能显著减少“做了很多，但无法交付”的情况。</p><h2 id="六、把完整项目压缩成一条垂直交付链" tabindex="-1">六、把完整项目压缩成一条垂直交付链 <a class="header-anchor" href="#六、把完整项目压缩成一条垂直交付链" aria-label="Permalink to &quot;六、把完整项目压缩成一条垂直交付链&quot;">​</a></h2><p>完整项目不能靠一句“从零实现”直接跨越。先建立可运行基线，再让代理定位入口、模块边界、数据模型、外部依赖和现有测试；人核对实现地图后，按能够独立演示的垂直切片推进。每个切片都应同时包含最小业务行为、必要测试与使用说明，避免先铺满接口、最后才发现系统无法集成。</p><p><img src="'+l+'" alt="图 5：完整项目从基线、垂直切片到验收"></p><h2 id="七、把交互能力归纳成一条闭环" tabindex="-1">七、把交互能力归纳成一条闭环 <a class="header-anchor" href="#七、把交互能力归纳成一条闭环" aria-label="Permalink to &quot;七、把交互能力归纳成一条闭环&quot;">​</a></h2><p>完整闭环可以概括为：用执行合同定义目标，用会话控制管理状态，用工程工作流收集证据，优先选择结构化接口完成可靠操作，最后通过 diff、测试和人工审查验收。遇到复杂项目，就把同一闭环复制到一个个垂直切片，而不是把所有风险积压到最终集成。</p><p><img src="'+c+'" alt="图 6：任务从意图经过证据反馈持续收敛"></p><p>真正让 AI 越改越准的，不是模型在会话里神秘地“理解了你”，而是每轮新增的上下文、约束和验证都在持续压缩错误空间。掌握这条逻辑后，Prompt、权限和工具不再是零散技巧，而是一套可以迁移到任何项目的协作系统。</p><h2 id="八、参考资料" tabindex="-1">八、参考资料 <a class="header-anchor" href="#八、参考资料" aria-label="Permalink to &quot;八、参考资料&quot;">​</a></h2><p><a href="https://coding.stormzhang.ai/codex/12-slash-commands" target="_blank" rel="noreferrer">Codex 系列第 12 篇：斜杠命令</a></p><p><a href="https://coding.stormzhang.ai/codex/13-prompting" target="_blank" rel="noreferrer">Codex 系列第 13 篇：Prompt 方法</a></p><p><a href="https://coding.stormzhang.ai/codex/14-workflows" target="_blank" rel="noreferrer">Codex 系列第 14 篇：常见工作流</a></p><p><a href="https://coding.stormzhang.ai/codex/17-computer-use" target="_blank" rel="noreferrer">Codex 系列第 17 篇：浏览器与 Computer Use</a></p><p><a href="https://coding.stormzhang.ai/codex/34-capstone" target="_blank" rel="noreferrer">Codex 系列第 34 篇：完整项目</a></p><p><a href="https://learn.chatgpt.com/docs/prompting" target="_blank" rel="noreferrer">OpenAI Prompting 官方文档</a></p><p><a href="https://learn.chatgpt.com/docs/computer-use" target="_blank" rel="noreferrer">OpenAI Computer Use 官方文档</a></p>',68)])])}const g=e(h,[["render",d]]);export{P as __pageData,g as default};
